\begin{itemize}[leftmargin=0.15in, label={}]
\item \textbf{Languages:} \small{C++, C/C++ coding proficiency, Python} \\
\textbf{ML/AI:} \small{DL/ML} \\
\textbf{Tools:} \small{OpenGL, CUDA} \\
\textbf{Other:} \small{Functional and performance models, Test plans, Memory isolation, Firmware, Process scheduling, PCIe, NVLink, CXL} \\
\end{itemize}
\section{Experience}
{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Engineer Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Reviewed the end-to-end GPU inference workflow interfaces because data/control handoffs between detection, classification, and OCR verification were hard to trace; produced roughly a 20+ page interface.}
    \resumeItem{Coordinated with software and verification engineers on a staged feature plan for the compute-interface behavior, which included Python scripts to generate test vectors.}
    \resumeItem{Developed functional and performance models in C++ for a new compute-interface behavior, then wrote unit tests that compared model predictions against measured throughput/latency from our inference pipeline-the model helped narrow which firmware/host-side assumptions to.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{July 2024 -- December 2024}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Created a C++ functional/performance reference model for a GPU-accelerated vision inference stage because the expected interface behavior was unclear-wrote roughly 12 acceptance checks covering correctness and performance.}
    \resumeItem{Monitored a Python test harness that ran the same inference workflow end-to-end (preprocess -> model -> postprocess) and compared outputs against the C++ model, which caught mismatches in tensor shapes.}
    \resumeItem{Coded Linux scripts and C/C++ unit tests to triage post-silicon regression failures, then traced each issue to specific interface assumptions such as memory layout and ordering.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Improved C++ interface feature designs by iterating on validation results from prior runs, updating models, revising test expectations, and refining design assumptions during internship work at NIT Jaipur.}
    \resumeItem{Built C/C++ tooling which analyzed OS scheduling and memory isolation constraints, so it identified GPU interface risks.}
    \resumeItem{Wrote C++ models and test plans at NIT Jaipur to evaluate how interfaces interact with PCIe, NVLink, and CXL, informing assumptions in the models and validating them across ~25 experimental conditions.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Research Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Supported GPU interface feature development by producing C++ engineering documentation and reviews covering design rationale, model methodology, and validation outcomes during internship at IIT Indore.}
    \resumeItem{Implemented CUDA-based performance modeling by learning GPU programming models and ML workload behavior, applying insights from Graphics/Compute APIs to refine validation scenarios and improve scheduling accuracy.}
    \resumeItem{Integrated Python automation into the validation workflow at IIT Indore, which ran test suites, collected metrics, and generated reports after each feature bring-up, saving the team about 5 hours a week during debugging.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

